extern "C" int adamod_tc_pair(const float* emb, const float* W, const float* bias, float* const* outs, int B,
                              cudaStream_t stream, int kbs_req, int stages_req, unsigned long long* diag) {
  if (B < 1 || B > 512) return 500;
  const int Bpad = (B + 15) / 16 * 16, h = Bpad / 2;
  const int h0 = h <= 128 ? h : ((h + 1) / 2 + 7) / 8 * 8;
  const int tmem_cols = Bpad <= 32 ? 32 : Bpad <= 64 ? 64 : Bpad <= 128 ? 128 : Bpad <= 256 ? 256 : 512;
  const int perK = kWBlk + h * 128, avail = kSmemDyn - 1024;
  int kbs = 1;
  for (int cand : {4, 3, 2}) if (avail / (cand * perK) >= 3) { kbs = cand; break; }
  if (kbs_req > 0) kbs = kbs_req;
  int stages = avail / (kbs * perK);
  if (stages > kMaxStages) stages = kMaxStages;
  if (stages_req > 0 && stages_req < stages) stages = stages_req;
  if (stages < 2) return 503;
  CUtensorMap mW, mE;
  cuuint64_t dW[3] = {(cuuint64_t)kBK, (cuuint64_t)kN, (cuuint64_t)kKB}, sW[2] = {(cuuint64_t)kD * 4, (cuuint64_t)kBK * 4};
  cuuint32_t bW[3] = {kBK, kRows, (cuuint32_t)kbs}, es[3] = {1, 1, 1};
  if (cuTensorMapEncodeTiled(&mW, CU_TENSOR_MAP_DATA_TYPE_TFLOAT32, 3, (void*)W, dW, sW, bW, es, CU_TENSOR_MAP_INTERLEAVE_NONE,
      CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_256B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE) != CUDA_SUCCESS) return 501;
  cuuint64_t dE[3] = {(cuuint64_t)kBK, (cuuint64_t)B, (cuuint64_t)kKB}, sE[2] = {(cuuint64_t)kD * 4, (cuuint64_t)kBK * 4};
  cuuint32_t bE[3] = {kBK, (cuuint32_t)h, (cuuint32_t)kbs};
  if (cuTensorMapEncodeTiled(&mE, CU_TENSOR_MAP_DATA_TYPE_TFLOAT32, 3, (void*)emb, dE, sE, bE, es, CU_TENSOR_MAP_INTERLEAVE_NONE,
      CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_256B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE) != CUDA_SUCCESS) return 502;
  static bool attr_set = false;
  if (!attr_set) { cudaFuncSetAttribute(tc_pair_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, kSmemDyn); attr_set = true; }
  OutPtrs op; for (int i = 0; i < 6; ++i) op.p[i] = outs[i];
  tc_pair_kernel<<<kN / kRows, 128, stages * kbs * perK + 1024, stream>>>(mW, mE, bias, op, B, h, h0, kbs, stages, tmem_cols, diag);
  return (int)cudaGetLastError();
}
