    uint64_t pol, ppol;
    asm volatile("createpolicy.fractional.L2::evict_first.b64 %0, 1.0;" : "=l"(pol));
    if (pfpol) asm volatile("createpolicy.fractional.L2::evict_normal.b64 %0, 1.0;" : "=l"(ppol)); else ppol = pol;
    int kp = 0;
    for (int i = 0; i < nIt; ++i) {
      const int s = i % stages;
      if (pfk) {
        const int lim = min(i * kbs + la + kbs, kKB);
        for (; kp < lim; kp += pfk)
          asm volatile("cp.async.bulk.prefetch.tensor.3d.L2.global.tile.L2::cache_hint [%0, {%1, %2, %3}], %4;"
                       ::"l"((uint64_t)&mapP), "r"(0), "r"(m0), "r"(kp), "l"(ppol) : "memory");
      }
