    const uint32_t idesc0 = ib | ((uint32_t)(2 * h0 >> 3) << 17), idesc1 = ib | ((uint32_t)(2 * h1 >> 3) << 17);
    for (int i = 0; i < nIt; ++i) {
      const int s = i % stages;
