        const uint32_t a = sbase + s * stageBytes + j * kWBlk, b = sbase + s * stageBytes + kbs * kWBlk + j * eBlk;
        const uint64_t da = sw128_desc(a), db0 = sw128_desc(b), db1 = sw128_desc(b + h0 * 128);
#pragma unroll
