          asm volatile("{ .reg .pred p; setp.ne.b32 p, %4, 0; tcgen05.mma.cta_group::2.kind::tf32 [%0], %1, %2, %3, p; }"
                       ::"r"(tmem), "l"(da + 2 * k), "l"(db0 + 2 * k), "r"(idesc0), "r"(acc));
          if (h1 > 0)
            asm volatile("{ .reg .pred p; setp.ne.b32 p, %4, 0; tcgen05.mma.cta_group::2.kind::tf32 [%0], %1, %2, %3, p; }"
                         ::"r"(tmem + 2 * h0), "l"(da + 2 * k), "l"(db1 + 2 * k), "r"(idesc1), "r"(acc));
        }
      }
      umma_commit_pair(smem_u32(&empty[s]));
    }
    umma_commit_pair(smem_u32(&accum));
  }
  __syncwarp();
  mbar_wait(smem_u32(&accum), 0);
  asm volatile("tcgen05.fence::after_thread_sync;");
  if (diag && threadIdx.x == 0) diag[blockIdx.x * 4 + 2] = clock64() - c_start;
  const int q = warp & 3, half = warp >> 2, nh = blockDim.x >> 7;
  const int m = m0 + q * 32 + lane;
